    '@size': notes('Size and spacing', 'Curves and corners'),
    '@curves': notes('Curves and corners', 'Stem ends'),
    '@ends': notes('Stem ends', 'Handwriting'),
    '@hand': notes('Handwriting', 'Choices'),
    '@choices': notes('Choices', 'The styles run'),
