    widths: { from: '// 6. Letter widths', to: '// 7. The letters' },
    letters: { from: '// 7. The letters', to: '// 8. A shaky hand' },
    shaky: { from: '// 8. A shaky hand', to: '// 9. Outlines' },
    outlines: { from: '// 9. Outlines', to: '// 10. Assembling' },
    text: { from: '// 10. Assembling', to: '})(typeof window' },
